mapper.select:
SELECT COUNT(*) FROM experiment_schedule WHERE status<>3
AND id<>#{id}
AND (lab_id=#{labId} OR teacher_id=#{teacherId}) AND start_time<#{endTime} AND end_time>#{startTime}

mapper.insert:
INSERT INTO experiment_attendance(schedule_id,student_id,status,check_in_time,remark,operator_id)
SELECT #{scheduleId},#{studentId},#{status},NOW(),#{remark},#{operatorId}
FROM experiment_schedule s JOIN class_student cs ON cs.class_id=s.class_id AND cs.student_id=#{studentId}
WHERE s.id=#{scheduleId}
ON DUPLICATE KEY UPDATE status=VALUES(status),check_in_time=NOW(),remark=VALUES(remark),operator_id=VALUES(operator_id)

mapper.select:
SELECT r.*,s.start_time,p.project_name,u.real_name AS student_name,g.real_name AS grader_name
FROM experiment_report r JOIN experiment_schedule s ON s.id=r.schedule_id
JOIN experiment_project p ON p.id=s.project_id JOIN `user` u ON u.id=r.student_id LEFT JOIN `user` g ON g.id=r.grader_id

    AND r.schedule_id=#{scheduleId}
    AND r.student_id=#{userId}
    AND s.teacher_id=#{userId}

ORDER BY r.submit_time DESC
